head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getMaxLength]<br/>Body Column 정보를 사용하여 특정 Column 의 maxLength 속성값을 반환합니다.",
    "validation" : [
        "Body Column 이 inputType='text','textarea','textImage','secret' 인 경우에 유효한 값을 반환합니다.",
        "columnInfo(필수) 파라미터로 maxLength 속성값을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "파라미터에 해당하는 Body Column 의 maxLength 속성값을 반환해야 합니다.",
        "Body Column 의 inputType 속성값이 'text','textarea','textImage','secret' 가 아니면 undefined 를 반환해야 합니다.",
        "파라미터가 유효하지 않으면 undefined 를 반환해야 합니다.",
        "setMaxLength() 메소드는 inputType 속성값 허용 목록에 'autoComplete' 를 포함하지만 getMaxLength() 메소드는 'autoComplete' 를 포함하지 않습니다.",
        "dataType='float' 인 Body Column 에 setMaxLength() 메소드로 maxLength 속성 설정 시 속성엔 -1 이 설정되어 getMaxLength() 메소드로 조회 시 -1 값이 반환되므로 주의해야 합니다.",
        "setCellMaxLength() 메소드로 Cell 단위에 설정된 maxLength 속성값은 getMaxLength() 메소드로 반환되지 않으며 Column 의 maxLength 속성보다 우선 적용됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_opt !== 'undefined') {
        $p.data.remove("dlt_opt");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스(숨김 포함) - 0:text(maxLength=10) / 1:textarea(maxLength=20, 숨김 setColumnVisible(1,false)) / 2:textImage(maxLength=15) / 3:secret(maxLength=8) / 4:autoComplete / 5:text+dataType=float(comp_init 에서 setMaxLength 적용) / 6:calendar / 7:custom(Column maxLength=12, typeGetter 로 각 Cell inputType=text). 데이터 Row 4개.\n[절차] columnInfo(인덱스) 선택 후 (getMaxLength 실행) 클릭. spec3 는 (setCellMaxLength 후 getMaxLength) 클릭.\n[확인] 0/1/2/3=maxLength 문자열 / 4=undefined(autoComplete 미포함) / 5=-1(float 주의) / 6=undefined(비 4종) / 99=undefined(무효 파라미터).\nspec3: 인덱스 7(custom) Row 0 Cell 에 setCellMaxLength(3) 적용 후 getMaxLength(7) 반환값 확인 + Row 0(Cell 설정 3) 과 Row 1(Column 설정 12) 의 편집창 maxLength 실측 비교. 인덱스 0(text) 호출 결과로 custom 이 아닌 Column 은 미적용임을 확인."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (Body Column id 와 동일한 컬럼 구성)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="c_text" name="c_text" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_area" name="c_area" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_img" name="c_img" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_secret" name="c_secret" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_auto" name="c_auto" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_float" name="c_float" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_cal" name="c_cal" dataType="text"></w2:column>';
    strDlt += '<w2:column id="c_custom" name="c_custom" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "c_text": "노트북", "c_area": "설명1", "c_img": "아이콘1", "c_secret": "1234", "c_auto": "서울", "c_float": "1234.56", "c_cal": "20260201", "c_custom": "노트북거치대" },
        { "c_text": "모니터", "c_area": "설명2", "c_img": "아이콘2", "c_secret": "5678", "c_auto": "부산", "c_float": "7890.12", "c_cal": "20260202", "c_custom": "모니터받침대" },
        { "c_text": "키보드", "c_area": "설명3", "c_img": "아이콘3", "c_secret": "9012", "c_auto": "대구", "c_float": "3456.78", "c_cal": "20260203", "c_custom": "키보드덮개" },
        { "c_text": "마우스", "c_area": "설명4", "c_img": "아이콘4", "c_secret": "3456", "c_auto": "인천", "c_float": "9012.34", "c_cal": "20260204", "c_custom": "마우스패드" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // autoComplete Column(인덱스 4) itemset 용 옵션 DataList (value ref=oCode, label ref=oLabel)
    let strOpt = '';
    strOpt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_opt" baseNode="list" repeatNode="map">';
    strOpt += '<w2:columnInfo>';
    strOpt += '<w2:column id="oCode" name="oCode" dataType="text"></w2:column>';
    strOpt += '<w2:column id="oLabel" name="oLabel" dataType="text"></w2:column>';
    strOpt += '</w2:columnInfo>';
    strOpt += '<w2:data use="true"></w2:data>';
    strOpt += '</w2:dataList>';
    $p.data.create(strOpt);
    dlt_opt.setJSON([
        { "oCode": "서울", "oLabel": "서울" },
        { "oCode": "부산", "oLabel": "부산" },
        { "oCode": "대구", "oLabel": "대구" },
        { "oCode": "인천", "oLabel": "인천" }
    ], false);

    // autoComplete Column itemset(nodeset) 조각 : label ref=oLabel, value ref=oCode
    let acItemset = '<w2:choices><w2:itemset nodeset="data:dlt_opt"><w2:label ref="oLabel"></w2:label><w2:value ref="oCode"></w2:value></w2:itemset></w2:choices>';

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 8컬럼 + gBody 8컬럼) - Header inputType 은 text, gBody 가 실제 inputType
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:900px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getMaxLength 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol1" value="text(ML=10)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="textarea(ML=20,숨김)"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol3" value="textImage(ML=15)"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="hcol4" value="secret(ML=8)"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol5" value="autoComplete"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol6" value="text/float"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="hcol7" value="calendar"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol8" value="custom(ML=12)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : text (maxLength=10) -> 유효값 "10"
    strTarget += '<w2:column width="110" style="" inputType="text" maxLength="10" id="c_text" dataList="c_text"></w2:column>';
    // index 1 : textarea (maxLength=20) -> setColumnVisible(1,false) 로 숨김 -> 숨김 포함 인덱스 검증용, 유효값 "20"
    strTarget += '<w2:column width="120" style="" inputType="textarea" maxLength="20" id="c_area" dataList="c_area"></w2:column>';
    // index 2 : textImage (maxLength=15) -> 유효값 "15". viewType=icon + imageSrc 로 셀에 아이콘+텍스트 표시
    strTarget += '<w2:column width="110" style="" inputType="textImage" maxLength="15" viewType="icon" imageSrc="/cm/images/base/ico_grid_add.svg" id="c_img" dataList="c_img"></w2:column>';
    // index 3 : secret (maxLength=8) -> 유효값 "8"
    strTarget += '<w2:column width="90" style="" inputType="secret" maxLength="8" id="c_secret" dataList="c_secret"></w2:column>';
    // index 4 : autoComplete (dlt_opt nodeset itemset -> 셀에 선택 가능한 아이템 표시) -> getMaxLength 미포함 -> undefined (@spec1)
    strTarget += '<w2:column width="100" style="" inputType="autoComplete" id="c_auto" dataList="c_auto">' + acItemset + '</w2:column>';
    // index 5 : text + dataType=float -> comp_init 에서 setMaxLength(5,6) 적용 -> -1 반환 (@spec2)
    strTarget += '<w2:column width="110" style="" inputType="text" dataType="float" id="c_float" dataList="c_float"></w2:column>';
    // index 6 : calendar (비 4종) -> undefined (@return)
    strTarget += '<w2:column width="110" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" id="c_cal" dataList="c_cal"></w2:column>';
    // index 7 : custom (Column maxLength=12) + typeGetter 로 각 Cell inputType="text" -> setCellMaxLength 적용 대상 (@spec3)
    strTarget += '<w2:column width="*" style="" inputType="custom" maxLength="12" typeGetter="scwin.target1_typeGetter" id="c_custom" dataList="c_custom"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 두번째 Column(c_area, 인덱스 1) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(1, false);

    // dataType='float' Column(인덱스 5) 에 setMaxLength 적용 -> 속성엔 -1 설정됨 (@spec2 사전 상태 세팅)
    target1.setMaxLength(5, 6);
}



// custom Column(인덱스 7) 의 각 Cell inputType 을 결정하는 typeGetter (setCellMaxLength 는 Cell inputType 이 text 등일 때만 동작)
scwin.target1_typeGetter = function (info) {
    return {
        "id": "custom_text_" + info.rowIndex + "_" + info.colIndex,
        "inputType": "text",
        "options": {}
    };
}



// getMaxLength 조회 (메인 검증)
scwin.btn_getMaxLength_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // getMaxLength : text/textarea/textImage/secret Column 의 maxLength 속성값 반환
    // (그 외 inputType / 유효하지 않은 파라미터 는 undefined)
    let result = target1.getMaxLength(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getMaxLength(" + columnInfo + ") -> 반환값: " + result);
}



// custom Column(인덱스 7) 의 특정 Row Cell 을 편집모드로 진입시켜 실제 렌더된 편집 input 요소의 maxLength 를 실측
scwin.getCellEditMaxLength = function (rowIndex) {
    target1.endEdit();

    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_7']");
    target1.setEditMode(td);

    let input = document.querySelector("input[id*='custom_text_" + rowIndex + "_7']");
    let maxLen = input ? input.getAttribute("maxlength") : "편집창 없음";

    target1.endEdit();
    return maxLen;
}



// @spec3 검증 : setCellMaxLength 로 Cell 단위 설정한 값은 getMaxLength 로 반환되지 않으며 Column maxLength 보다 우선 적용됨
//  인덱스 7(custom, Column maxLength=12) 의 Row 0 Cell 에 setCellMaxLength(0,7,3) 적용
scwin.btn_spec3_onclick = function () {
    let ret = target1.setCellMaxLength(0, 7, 3);
    let colMax = target1.getMaxLength(7);

    // Cell 설정 Row 0(3) 과 미설정 Row 1(Column maxLength=12) 의 편집창 maxLength 실측 비교
    let row0Max = scwin.getCellEditMaxLength(0);
    let row1Max = scwin.getCellEditMaxLength(1);

    // 대조 : custom 이 아닌 text Column(인덱스 0) 에 대한 호출 결과
    let retText = target1.setCellMaxLength(0, 0, 3);

    wf_body_bottom.getObj("scwin").setReturnValue("setCellMaxLength(0,7,3) 반환값: " + ret);
    wf_body_bottom.getObj("scwin").setReturnValue("getMaxLength(7) 반환값: " + colMax);
    wf_body_bottom.getObj("scwin").setReturnValue("편집창 maxLength 실측 -> Row 0(Cell 설정 3): " + row0Max + " / Row 1(Column 설정 12): " + row1Max);
    wf_body_bottom.getObj("scwin").setReturnValue("setCellMaxLength(0,0,3) 반환값(인덱스 0 은 custom Column 아님): " + retText);
}
